"""
    Generates the first n Fibonacci numbers.
    Adopted from: https://docs.python.org/3/tutorial/modules.html
    """
def fibonacci(n: int) -> list[int] {
    result = [];
    (a, b) = (0, 1);
    while len(result) < n {
        result.append(b);
        (a, b) = (b, a + b);
    }
    return result;
}

def rgb(value: float | int, minimum: float | int, maximum: float | int) -> tuple[float, float, float] {
    """
    Calculates an rgb color of a value depending of
    the minimum and maximum values.
    """
    value = float(value);
    minimum = float(minimum);
    maximum = float(maximum);
    ratio = 0.0 if minimum == maximum else 2 * (value - minimum) / (maximum - minimum);
    b = int(max(0, 255 * (1 - ratio)));
    r = int(max(0, 255 * (ratio - 1)));
    g = 255 - b - r;
    return (r / 255.0, g / 255.0, b / 255.0);
}

def pad_to_max_seq_length(
    ls: list[int],
    max_seq_length: int,
    pad_idx: int = 0,
    pad_right: bool = True,
    check: bool = True
) -> list[int] {
    """Apply padding to an input sequence."""
    padding = [pad_idx] * (max_seq_length - len(ls));
    result = ls + padding if pad_right else padding + ls;
    if check {
        assert len(result) == max_seq_length;
    }
    return result;
}

