def comp(z1: float, z2: float, tol: float) -> bool {
    """Return a bool indicating whether the error between z1 and z2 is <= tol."""
    if not z1 {
        (z1, z2) = (z2, z1);
    }
    if not z1 {
        return True;
    }
    diff = abs(z1 - z2);
    az1 = abs(z1);
    if z2 and az1 > 1 {
        return diff / az1 <= tol;
    } else {
        return diff <= tol;
    }
}

