"""Returns the number of times 8 appears as a digit of x.

    >>> num_eights(3)
    0
    >>> num_eights(8)
    1
    >>> num_eights(88888888)
    8
    >>> num_eights(2638)
    1
    >>> num_eights(86380)
    2
    >>> num_eights(12345)
    0
    """
def num_eights(x: int) -> int {
    def is_eight(x: int) -> int {
        if x == 8 {
            return 1;
        } else {
            return 0;
        }
    }
    if x < 10 {
        return is_eight(x);
    } else {
        return num_eights(x // 10) + is_eight(x % 10);
    }
}

