"""Merges two sorted lists.

    >>> merge([1, 3, 5], [2, 4, 6])
    [1, 2, 3, 4, 5, 6]
    >>> merge([], [2, 4, 6])
    [2, 4, 6]
    >>> merge([1, 2, 3], [])
    [1, 2, 3]
    >>> merge([5, 7], [2, 4, 6])
    [2, 4, 5, 6, 7]
    """
def merge(lst1: list[int], lst2: list[int]) -> list[int] {
    if lst1 == [] {
        return lst2;
    } elif lst2 == [] {
        return lst1;
    } elif lst1[0] <= lst2[0] {
        return lst1[:1] + merge(lst1[1:], lst2);
    } else {
        return lst2[:1] + merge(lst1, lst2[1:]);
    }
}

