"""Cross Product.

    Given vectors a and b, calculate the cross product.
    """
def cross(a: list[float], b: list[float]) -> list[float] {
    c = [
        a[1] * b[2] - a[2] * b[1],
        a[2] * b[0] - a[0] * b[2],
        a[0] * b[1] - a[1] * b[0]
    ];
    return c;
}

"""
    Linear regression function.

    :param clear_x: cleared_x
    :type clear_x : list
    :param clear_y: cleared_y
    :type clear_y : list
    :return: [slope,intercept]
    """
def estimate_coef(clear_x: list[float], clear_y: list[float]) -> list[float] {
    try {
        n = len(clear_x);
        mean_x = sum(clear_x) / n;
        mean_y = sum(clear_y) / n;
        SS_xy = 0;
        SS_xx = 0;
        for (index, item) in enumerate(clear_x) {
            SS_xx += item ** 2;
            SS_xy += item * clear_y[index];
        }
        SS_xx -= n * (mean_x ** 2);
        SS_xy -= n * mean_x * mean_y;
        B1 = SS_xy / SS_xx;
        B0 = mean_y - B1 * mean_x;
        return [B1, B0];
    } except (TypeError, ZeroDivisionError, OverflowError, ValueError) {
        return [0, 0];
    }
}

