(can be found inside def process_inputs; dicts pre-processed inside the
function)
"""
def multi_inputs(dicts: dict[str, str]) -> dict[str, str | list[str]] {
    dict_list: dict[str, str | list[str]] = {};
    for (k, v) in dicts.items() {
        if k[-1:].isnumeric() is False {
            dict_list.update({k: v});
        } elif k[:-2] not in dict_list {
            dict_list.update({k[:-2]: v});
        } elif k[:-2] in dict_list {
            if not isinstance(dict_list[k[:-2]], list) {
                new_list = [dict_list[k[:-2]]];
            } else {
                new_list = dict_list[k[:-2]];
            }
            new_list.append(v);
            dict_list.update({k[:-2]: new_list});
        }
    }
    return dict_list;
}

"""Sorting function, by just comparing elements to elements, requires implementation of __gt__. Probably not the fastest version (n**2)."""
def compsort(q: list[int]) -> list[int] {
    ret: list[int] = [];
    for (j, qq) in enumerate(q) {
        for (i, k) in enumerate(ret) {
            if k > qq {
                ret.insert(i, qq);
                break;
            }
        }
        if len(ret) <= j {
            ret.append(qq);
        }
    }
    return ret;
}

"""Compute intensity of the first isotopologue M0.

Handle element X with specific abundance. X represents C with default isotopic abundance.
"""
def compute_M0_nl(formula: dict[str, int], abundance: dict[str, float]) -> float {
    M0_intensity = (
        abundance["C[12]"] ** formula["C"]
        * abundance["X[12]"] ** formula["X"]
        * abundance["H[1]"] ** formula["H"]
        * abundance["N[14]"] ** formula["N"]
        * abundance["O[16]"] ** formula["O"]
        * abundance["S[32]"] ** formula["S"]
    );
    return M0_intensity;
}

