"""from https://stackoverflow.com/a/32558749"""
def levenshtein_distance(s1: str, s2: str) -> int {
    if len(s1) > len(s2) {
        (s1, s2) = (s2, s1);
    }
    distances = range(len(s1) + 1);
    for (i2, c2) in enumerate(s2) {
        distances_ = [i2 + 1];
        for (i1, c1) in enumerate(s1) {
            if c1 == c2 {
                distances_.append(distances[i1]);
            } else {
                distances_.append(1 + min((distances[i1], distances[i1 + 1], distances_[-1])));
            }
        }
        distances = distances_;
    }
    return distances[-1];
}

"""joint fraction number
    Args:
        text_list (list): text list.

    Returns:
        (list): processed text list.
    """
def joint_number(text_list: list[str]) -> list[str] {
    new_list = [];
    i = 0;
    while i < len(text_list) {
        if text_list[i] == '(' and i + 4 < len(text_list) and text_list[i + 4] == ')' {
            sub = ''.join(text_list[i:i + 5]);
            new_list.append(sub);
            i = i + 5;
        } else {
            new_list.append(text_list[i]);
            i += 1;
        }
    }
    return new_list;
}

"""
Converts an ASN1 Tag into the corresponding byte representation
:param value: The tag to convert
:return: The integer array
"""
def tagToByte(value: int) -> list[int] {
    if value <= 255 {
        return [value];
    } elif value <= 65535 {
        return [value >> 8, value & 255];
    } elif value <= 16777215 {
        return [value >> 16, (value >> 8) & 255, value & 255];
    } elif value <= 4294967295 {
        return [
            value >> 24,
            (value >> 16) & 255,
            (value >> 8) & 255,
            value & 255
        ];
    }
    raise Exception("tagToByte: tag is too big");
}

