"""
Update the harmony memory if necessary with the given harmony. If the given harmony is better than the worst
harmony in memory, replace it. This function doesn't allow duplicate harmonies in memory.
"""
def update_harmony_memory(
    considered_harmony: list[float], considered_fitness: float, harmony_memory: list[tuple[list[float], float]]
) -> list[tuple[list[float], float]] {
    if (considered_harmony, considered_fitness) not in harmony_memory {
        worst_index = None;
        worst_fitness = float('+inf');
        for (i, (harmony, fitness)) in enumerate(harmony_memory) {
            if fitness < worst_fitness {
                worst_index = i;
                worst_fitness = fitness;
            }
        }
        if considered_fitness > worst_fitness {
            harmony_memory[worst_index] = (considered_harmony, considered_fitness);
        }
    }
    return harmony_memory;
}

"""
This function allows the user to split a string by using different
separators.

Note: This version is faster than using the (s)re.split method (I tested it
with timeit).

Parameters:
* source_string: string to be splitted
* separators: string containing the characters used to split the source
  string.
* split_by: all the ocurrences of the separators will be replaced by this
  character, then the split will be done. It defaults to '|' (pipe)
"""
def multiple_split(
    source_string: str, separators: str, split_by: str = '\n'
) -> list[str] {
    translate_to = split_by * len(separators);
    translation = str.maketrans(separators, translate_to);
    return source_string.translate(translation).split(split_by);
}

