"""Extract the passed form data into the self.user_options variable."""
def options_from_form(spawner: dict, formdata: dict[str, list[str]]) -> dict {
    options = {};
    if formdata.get('is_custom_image', ["off"])[0] == "on" {
        options["image"] = formdata.get('custom_image', [None])[0];
    } else {
        options["image"] = formdata.get('defined_image', [None])[0];
    }
    options["cpu_limit"] = formdata.get('cpu_limit', [None])[0];
    options["mem_limit"] = formdata.get('mem_limit', [None])[0];
    options["is_mount_volume"] = formdata.get('is_mount_volume', ["off"])[0];
    options["days_to_live"] = formdata.get('days_to_live', [None])[0];
    env = {};
    env_lines = formdata.get('env', ['']);
    for line in env_lines[0].splitlines() {
        if line {
            (key, value) = line.split('=', 1);
            env[key.strip()] = value.strip();
        }
    }
    options['env'] = env;
    options['shm_size'] = formdata.get('shm_size', [None])[0];
    options['gpus'] = formdata.get('gpus', [None])[0];
    return options;
}

""" rgba2int: Converts an RGB value into an integer

    :param r The red value (0-255)
    :param g The green value (0-255)
    :param b The blue value (0-255)

    :returns: The RGB value compact into a 24 byte integer.
    """
def rgb2int(r: int, g: int, b: int) -> int {
    (r, g, b) = (int(abs(r)), int(abs(g)), int(abs(b)));
    return (r << 16) + (g << 8) + b;
}

"""
    Method to obtain number of decimal places to report on plots

    Args:

        delta: (float), a float representing the change in two y values on a plot, used to obtain the plot axis spacing size

    Return:

        (int), an integer denoting the number of decimal places to use

    """
def rounder(delta: float) -> int {
    if 0.001 <= delta < 0.01 {
        return 3;
    } elif 0.01 <= delta < 0.1 {
        return 2;
    } elif 0.1 <= delta < 1 {
        return 1;
    } else {
        return 0;
    }
}

