glob UINT64_MASK = 0xFFFFFFFFFFFFFFFF;

""" Right rotate the number x by c bytes, for 64-bits numbers."""
def rightrotate_64(x: int, c: int) -> int {
    x &= UINT64_MASK;
    return ((x >> c) | (x << (64 - c))) & UINT64_MASK;
}

"""Takes a character from given string,
    shifts it secret times and return the
    character from lst depending on case of
    the taken character."""
def find_char(char: str, secret: int, lst: str) -> str {
    pos = lst.index(char);
    offset = (pos + secret) % 26;
    return lst[offset];
}

"""
    Takes a string and breaks it into lines with <= n characters per line.

    Useful because psql queries have to have < 212 chars per line.
    """
def cut_lines_to_n(string: str, n: int = 200) -> str {
    out = [];
    lines = string.split("\n");
    for line in lines {
        newline = "";
        words = line.split(" ");
        for word in words {
            if len(newline + word) + 1 > n {
                out.append(newline.strip());
                newline = word;
            } else {
                newline += " " + word;
            }
        }
        out.append(newline);
    }
    return "\n".join(out);
}

"""Check that every player does not come in 1st and does not come in last
    at least once each."""
def check_games(games: list[dict[str, int]]) -> tuple[list[str], list[str]] | tuple[None, None] {
    pc = dict();
    for game in games {
        max_rank = 0;
        max_user = None;
        for (user, rank) in game.items() {
            if rank > 1 {
                pc.setdefault(user, [1, 1])[1] = 0;
            }
            if rank > max_rank {
                if max_user {
                    pc.setdefault(max_user, [1, 1])[0] = 0;
                }
                max_rank = rank;
                max_user = user;
            } elif rank < max_rank {
                pc.setdefault(user, [1, 1])[0] = 0;
            }
        }
    }
    missing_wl = sum(w + l for (w, l) in pc.values());
    if missing_wl > 0 {
        winners = list();
        losers = list();
        for (player, (win, loss)) in pc.items() {
            if not win and not loss {
                continue;
            }
            if win and loss {
                raise Exception("Player with neither win or loss %s" % (player,));
            }
            if win {
                losers.append(player);
            } else {
                winners.append(player);
            }
            print("Player %s has no %s" % (player, "win" if win else "loss"));
        }
        return (winners, losers);
    }
    return (None, None);
}

