"""
Returns n-th Fibonacci number
n must be more than 0, otherwise it raises a ValueError.
>>> recursive_fibonacci_cache(0)
0
>>> recursive_fibonacci_cache(1)
1
>>> recursive_fibonacci_cache(2)
1
>>> recursive_fibonacci_cache(10)
55
>>> recursive_fibonacci_cache(-2)
Traceback (most recent call last):
    ...
ValueError: n must be more or equal than 0
"""
def recursive_fibonacci_cache(n: int) -> int {
    cache: dict[int, int] = {};
    def _fib(_n: int) -> int {
        if _n < 0 {
            raise ValueError('n must be more or equal than 0');
        }
        if _n == 0 {
            return 0;
        } elif _n == 1 {
            return 1;
        }
        if _n not in cache {
            if _n - 1 not in cache {
                cache[_n - 1] = _fib(_n - 1);
            }
            if _n - 2 not in cache {
                cache[_n - 2] = _fib(_n - 2);
            }
            cache[_n] = cache[_n - 1] + cache[_n - 2];
        }
        return cache[_n];
    }
    return _fib(n);
}

"""finds the closest number in sorted list l to n"""
def closest(l: list[int | float], n: int | float) -> int | float {
    mid = int(len(l) / 2);
    if len(l) < 7 {
        return min(l, key=lambda (e: int | float) { abs(n - e); });
    } elif n > l[mid] {
        return closest(l[mid:], n);
    } else {
        return closest(l[:mid + 1], n);
    }
}

"""
    Returns the median of the elements of the iterable `x`.

    If the number of elements in `x` is even, the arithmetic mean of the upper
    and lower median values is returned.

    >>> median([3, 7, 4])
    4

    >>> median([3, 7, 4, 45])
    5.5
    """
def median(x: list[int | float]) -> int | float {
    s = sorted(x);
    n = len(s);
    if n % 2 == 1 {
        return s[(n - 1) // 2];
    } else {
        m = n // 2;
        return 0.5 * (s[m - 1] + s[m]);
    }
}

"""
    :type s: str
    :rtype: str
    """
def decode_string(s: str) -> str {
    stack: list[tuple[str, int]] = [];
    cur_num = 0;
    cur_string = '';
    for c in s {
        if c == '[' {
            stack.append((cur_string, cur_num));
            cur_string = '';
            cur_num = 0;
        } elif c == ']' {
            (prev_string, num) = stack.pop();
            cur_string = prev_string + num * cur_string;
        } elif c.isdigit() {
            cur_num = cur_num * 10 + int(c);
        } else {
            cur_string += c;
        }
    }
    return cur_string;
}

