"""
    [1/a^2, 0, 1/b^2, 0, 0, -1]
    """
def get_ellipse_equation_coefficient_by_simplest_focus_add(
    x1: float, y1: float, x2: float, y2: float, add: float
) -> list[float] {
    if y1 == 0 {
        a = add / 2;
        aa = a * a;
        c = abs(x1);
        bb = aa - c ** 2;
        return [1 / aa, 0, 1 / bb, 0, 0, -1];
    }
    b = add / 2;
    bb = b * b;
    c = abs(y1);
    aa = bb - c ** 2;
    return [1 / aa, 0, 1 / bb, 0, 0, -1];
}

""" Convert the stack dumps and sample counts into the flamegraph format.

    Return a list of lines.
    """
def to_flamegraph(stacks: dict[str, list[str]], counts: dict[str, int]) -> list[str] {
    lines = [];
    for id in counts {
        stack = ";".join(reversed(stacks[id]));
        count = counts[id];
        lines.append('{0} {1}'.format(stack, count));
    }
    return lines;
}

"""Extracts the sprreadsheet id from an url."""
def extract_spreadsheet_id(string: str) -> str {
    if "/edit" in string {
        string = string.split("/edit")[0];
    }
    if "/" in string {
        string = string.rstrip("/");
        string = string.split("/")[-1];
        string = string.split("&")[0];
        string = string.split("#")[0];
    }
    return string;
}

"""
    :param content:
    :param indent:
    :return:
    """
def _indent(content: str | list[str], indent: int) -> str | list[str] {
    if indent == 0 {
        return content;
    } else {
        pad = " " * indent;
        if isinstance(content, list) {
            return ["".join([pad, line]) for line in content];
        } else {
            return "".join([pad, content]);
        }
    }
}

