"""Given two polyline vertex lists, append them if needed.

Polylines to be appended will have the last coordinate of
the first vertex list be the same as the first coordinate of the
second vertex list. When appending, we need to eliminate
one of these coordinates.

Args:
    current_vl (list): First of two lists of vertexes to check.
    next_vl (list): Second of two lists of vertexes to check.

Returns:
    tuple: Tuple:

    1. ``True`` if the vertexes were appended, otherwise ``False``.
    2. New vertex list if appended (otherwise ignored).
"""
def polylineAppendCheck(current_vl: list[tuple[float, float, float]], next_vl: list[tuple[float, float, float]]) -> tuple[bool, list[tuple[float, float, float]]] {
    was_appended = False;
    appended_list = [];
    last = current_vl[-1];
    first = next_vl[0];
    if last[0] == first[0] and last[1] == first[1] and last[2] == first[2] {
        was_appended = True;
        appended_list = current_vl[:-1] + next_vl;
    }
    return (was_appended, appended_list);
}

"""
Checks if a packet is a magic packet, returns
True or False.

Args:
    data (bytes): the payload from a packet

"""
def is_magic_packet(data: bytes) -> bool {
    data_hex = data.hex().lower();
    sync = data_hex[:12];
    if sync == 'f' * 12 {
        mac = data_hex[12:24];
        magic = sync + mac * 16;
        if len(data_hex) == len(magic) {
            return magic == data_hex;
        } else {
            return magic == data_hex[:-12];
        }
    } else {
        return False;
    }
}

