"""
    http://code.activestate.com/recipes/198157-improve-dictionary-lookup-performance/
    Created by Raymond Hettinger on Sun, 4 May 2003 (PSF)
    Reduce average dictionary lookup time by making the internal tables more sparse.
    Improve dictionary sparsity.

    The dict.update() method makes space for non-overlapping keys.
    Giving it a dictionary with 100% overlap will build the same
    dictionary in the larger space.  The resulting dictionary will
    be no more that 1/3 full.  As a result, lookups require less
    than 1.5 probes on average.

    Example:
    >>> sparsify({1: 3, 4: 5})
    {1: 3, 4: 5}
    """
def sparsify(d: dict[int, int]) -> dict[int, int] {
    e = d.copy();
    d.update(e);
    return d;
}

"""
    Converts a string formula into a series of tokens for evaluation

    Takes a string and divides it into a list of individual string tokens.
    Special tokens include ``"(", ")", "+", "^", "[", "]", "=", "~"``,
    where these have the expected Python behavior, with ``"="`` and ``"~"``
    separating the LHS and RHS of the formula. All other special characters
    are considered to be non-special in this language and will only be split
    up based on whitespace. The LHS and all white space are removed. Note
    also that ``"call"`` is a protected keyword here, as it is used to
    designate a function call operation.

    :param formula: string formula to be parsed
    """
def _tokenize_string(formula: str) -> list[str] {
    assert isinstance(formula, str);
    token_list: list[str] = [];
    accumulated = "";
    for char in formula {
        if char in ["(", ")", "+", "^", " ", "[", "]", "=", "~"] {
            if not accumulated == "" {
                token_list.append(accumulated);
            }
            token_list.append(char);
            accumulated = "";
        } elif char == "*" {
            if accumulated == "*" {
                token_list.append("^");
                accumulated = "";
            } elif not accumulated == "" {
                token_list.append(accumulated);
                accumulated = "*";
            } else {
                accumulated = "*";
            }
        } else {
            if accumulated == "*" {
                token_list.append(accumulated);
                accumulated = "";
            }
            accumulated += char;
        }
    }
    if not accumulated == "" {
        token_list.append(accumulated);
    }
    outlist: list[str] = [];
    for item in token_list {
        if not item in [" ", "[", "]"] {
            outlist.append(item);
        } elif item == "[" {
            outlist.append(outlist.pop() + item);
        } elif item == "]" {
            if len(outlist) < 2 {
                raise SyntaxError("error in using square brackets in formula input");
            }
            outlist.append(outlist.pop(-2) + outlist.pop() + item);
        }
    }
    if outlist[0] == "y" {
        outlist.pop(0);
    }
    if outlist[0] in ["=", "~"] {
        outlist.pop(0);
    }
    for item in outlist {
        if (not "[" in item and "]" in item) or (not "]" in item and "[" in item) {
            raise SyntaxError("cannot nest operators in square brackets in formula input");
        }
        if item == "call" {
            raise SyntaxError("'call' cannot be used as a variable name in formula input");
        }
        if item in ["=", "~"] {
            raise SyntaxError("LHS in formula is not correctly specified");
        }
    }
    return outlist;
}

"""
    Number contiguous elements in an array with the information of the missing
    indices.
    """
def split_and_number(strips: list[object], missing_indices: list[int]) -> list[tuple[int, object]] {
    remapped_strips: list[tuple[int, object]] = [];
    j = 0;
    missing_indices.sort();
    for x in strips {
        if j in missing_indices {
            while j in missing_indices {
                j += 1;
            }
        }
        remapped_strips.append((j, x));
        j += 1;
    }
    return remapped_strips;
}

