"""Takes a type encoding string and outputs a list of the separated type codes.
Currently does not handle unions or bitfields and strips out any field width
specifiers or type specifiers from the encoding.  For Python 3.2+, encoding is
assumed to be a bytes object and not unicode.

Examples:
parse_type_encoding('^v16@0:8') --> ['^v', '@', ':']
parse_type_encoding('{CGSize=dd}40@0:8{CGSize=dd}16Q32') --> ['{CGSize=dd}', '@', ':', '{CGSize=dd}', 'Q']
"""
def parse_type_encoding(encoding: bytes) -> list[bytes] {
    type_encodings = [];
    brace_count = 0;
    bracket_count = 0;
    typecode = b'';
    for c in encoding {
        if isinstance(c, int) {
            c = bytes([c]);
        }
        if c == b'{' {
            if typecode and typecode[-1:] != b'^' and brace_count == 0 and bracket_count == 0 {
                type_encodings.append(typecode);
                typecode = b'';
            }
            typecode += c;
            brace_count += 1;
        } elif c == b'}' {
            typecode += c;
            brace_count -= 1;
            assert brace_count >= 0;
        } elif c == b'[' {
            if typecode and typecode[-1:] != b'^' and brace_count == 0 and bracket_count == 0 {
                type_encodings.append(typecode);
                typecode = b'';
            }
            typecode += c;
            bracket_count += 1;
        } elif c == b']' {
            typecode += c;
            bracket_count -= 1;
            assert bracket_count >= 0;
        } elif brace_count or bracket_count {
            typecode += c;
        } elif c in b'0123456789' {
            ;
        } elif c in b'rnNoORV' {
            ;
        } elif c in b'^cislqCISLQfdBv*@#:b?' {
            if typecode and typecode[-1:] == b'^' {
                typecode += c;
            } else {
                if typecode {
                    type_encodings.append(typecode);
                }
                typecode = c;
            }
        }
    }
    if typecode {
        type_encodings.append(typecode);
    }
    return type_encodings;
}

"""
Check buildings of unique height in each row.

Return True if buildings in a row have unique length, False otherwise.
"""
def check_uniqueness_in_rows(board: list[str]) -> bool {
    for row in board[1:-1] {
        row = list(row[1:-1]);
        while '*' in row {
            row.remove('*');
        }
        if len(set(row)) != len(row) {
            return False;
        }
    }
    return True;
}

"""
Returns the sum of all integers in the range ``[a, b]``, i.e. from ``a`` to
``b`` inclusive.

See

- https://math.stackexchange.com/questions/1842152/finding-the-sum-of-numbers-between-any-two-given-numbers
"""
def sum_of_integers_in_inclusive_range(a: int, b: int) -> int {
    return int((b - a + 1) * (a + b) / 2);
}

"""Accuracy for Root Cause Analysis with multiple causes.
Refined from the Acc metric in TBAC paper.
"""
def my_acc(scoreList: list[tuple[str, float]], rightOne: list[str], n: int | None = None) -> float {
    node_rank = [_[0] for _ in scoreList];
    if n is None {
        n = len(scoreList);
    }
    s = 0.0;
    for i in range(len(rightOne)) {
        if rightOne[i] in node_rank {
            rank = node_rank.index(rightOne[i]) + 1;
            s += (n - max(0, rank - len(rightOne))) / n;
        } else {
            s += 0;
        }
    }
    s /= len(rightOne);
    return s;
}

