"""Assigns the total number of dependencies to each node."""
def _count_dependencies(graph: dict[str, list[str]]) -> dict[str, int] {
    dependency_counter = {parent: 0 for parent in graph};
    for current_node in graph {
        stack = [[current_node, iter(graph[current_node])]];
        visited = set();
        visited.add(current_node);
        while stack {
            (parent, children_iter) = stack[-1];
            try {
                child = next(children_iter);
                if child not in visited {
                    visited.add(child);
                    dependency_counter[current_node] += 1;
                    stack.append([child, iter(graph[child])]);
                }
            } except StopIteration {
                stack.pop();
            }
        }
    }
    return dependency_counter;
}

"""
    Definition
    ---
    Method to check if point is valid and clear of obstacles

    Parameters
    ---
    point : node of intrest
    validPoints : list of all valid points
    clearance : minimum distance required from obstacles

    Returns
    ---
    bool : True if point is valid, False othervise
    """
def isPointValid(point: tuple[int, int], validPoints: list[tuple[int, int]], clearance: int) -> bool {
    for i in range(-clearance, clearance) {
        for j in range(-clearance, clearance) {
            if not (point[0] + i, point[1] + j) in validPoints {
                return False;
            }
        }
    }
    return True;
}

