def from_u16(n: int) -> int {
    """Reinterpret the unsigned 16-bit integer `n` as a signed integer."""
    if n >= 2 ** 15 {
        return -(2 ** 16 - n);
    } else {
        return n;
    }
}

def add(a: list[list[int]], b: list[list[int]]) -> list[list[int]] {
    """ Addiert die beiden Matrizen a, b komponentenweise.
    Gibt das Resultat der Addition als neue Matrix c aus. """
    n = len(a);
    c = [[a[i][j] + b[i][j] for j in range(n)] for i in range(n)];
    return c;
}

