def find(n: int) -> int {
    """
    Finds the sum of all multiples of 3 and 5 of an integer.
    :param n: an integer value.
    :return: the sum of all multiples of 3 and 5.
    """
    return sum(x for x in range(n + 1) if x % 5 == 0 or x % 3 == 0);
}

def bottom_up_cut_rod(price: list[int], length: int) -> float {
    """ bottom up implementation of cut rod memoized algorithm """
    incomelst = [float("-Inf") for _ in range(length + 1)];
    incomelst[0] = 0;
    for j in range(1, length + 1) {
        income = float("-Inf");
        for i in range(j) {
            income = max(income, price[i] + incomelst[j - i - 1]);
        }
        incomelst[j] = income;
    }
    return incomelst[length];
}

def _clear_bits(basis_state: int, apply_qubits: list[int]) -> int {
    """ Set bits specified in apply_qubits to zero in the int basis_state. """
    return basis_state - (sum(1 << i for i in apply_qubits) & basis_state);
}

