        return "{}{}{}".format(last, txt[1:-1], first);
    }
    return "Incompatible.";
}

"""Precondition: L is sorted from smallest to largest, and all items in L can be compared to v.
Return the index of the first occurrence of v in L, or -1 if v is not in L."""
def binary_search(L: list[int], v: int) -> int {
    b = 0;
    e = len(L) - 1;
    while b <= e {
        m = (b + e) // 2;
        if L[m] < v {
            b = m + 1;
        } else {
            e = m - 1;
        }
    }
    if b == len(L) or L[b] != v {
        return -1;
    } else {
        return b;
    }
}

