"""Determine whether some permutation A', B' of arrays A and B satisfies
A'[i] + B'[i] >= k for all i. Sort A ascending and B descending, then compare
pairwise."""
def two_arrays(k: int, A: list[int], B: list[int]) -> str {
    A.sort();
    B.sort(reverse=True);
    for (a, b) in zip(A, B) {
        if a + b < k {
            return "NO";
        }
    }
    return "YES";
}

