"""Returns a sublist with the top k elements from a givenlist. Accepts key"""
def topk(l: list[int], k: int, key: Callable[[int], int] = lambda (x: int) { x; }) -> list[int] {
    (idx, _) = zip(
        *sorted(enumerate(l), key=lambda (x: tuple[int, int]) { key(x[1]); }, reverse=True)
    );
    return [l[i] for i in idx[0:k]];
}

"""
	cov = number of bases / length of genome
	relative abundance = [(cov) / sum(cov for all genomes)] * 100
	"""
def relative_abundance(coverage: dict[str, list[float]]) -> dict[str, list[float]] {
    relative: dict[str, list[float]] = {};
    sums: list[float] = [];
    for genome in coverage {
        for cov in coverage[genome] {
            sums.append(0);
        }
        break;
    }
    for genome in coverage {
        index = 0;
        for cov in coverage[genome] {
            sums[index] += cov;
            index += 1;
        }
    }
    for genome in coverage {
        index = 0;
        relative[genome] = [];
        for cov in coverage[genome] {
            if sums[index] == 0 {
                relative[genome].append(0);
            } else {
                relative[genome].append((cov / sums[index]) * float(100));
            }
            index += 1;
        }
    }
    return relative;
}

