        return None;
    }
    if src is None {
        return dst;
    }
    if path is None {
        path = [];
    }
    for key in src {
        if key in dst {
            if isinstance(dst[key], dict) and isinstance(src[key], dict) {
                merge(dst[key], src[key], path + [str(key)], abort_conflict);
            } elif dst[key] == src[key] {
                ;
            } elif abort_conflict {
                raise ValueError('Conflict at %s' % '.'.join(path + [str(key)]));
            } else {
