glob UINT16_HIGH_MASK = 0xFF00;
glob UINT16_LOW_MASK = 0xFF;
glob UINT32_MASK_1 = 0xFF000000;
glob UINT32_MASK_2 = 0x00FF0000;
glob UINT32_MASK_3 = 0x0000FF00;
glob UINT32_MASK_4 = 0x000000FF;

"""
    Swap the endianness of a number
    """
def _swap_endian(val: int, length: int) -> int {
    if length <= 8 {
        return val;
    }
    if length <= 16 {
        return (val & UINT16_HIGH_MASK) >> 8 | (val & UINT16_LOW_MASK) << 8;
    }
    if length <= 32 {
        return (
            (val & UINT32_MASK_1) >> 24
            | (val & UINT32_MASK_2) >> 8
            | (val & UINT32_MASK_3) << 8
            | (val & UINT32_MASK_4) << 24
        );
    }
    raise Exception('Cannot swap endianness for length ' + length);
}

