    to change the colors to new ones.
    """
def recolor_by_frequency(colors: dict) -> dict {
    replace_dict = {
        val: ind
        for (ind, val) in enumerate(
            sorted(
                set(colors.values()),
                key=lambda (x: int) { list(colors.values()).count(colors[x]); }
            )
        )
    };
    result_dict = {};
    for key in colors {
