"""
    returns the volume of the primitive cell: |a1.(a2xa3)|
    """
def cell_volume(a1: list[float], a2: list[float], a3: list[float]) -> float {
    a_mid_0 = a2[1] * a3[2] - a2[2] * a3[1];
    a_mid_1 = a2[2] * a3[0] - a2[0] * a3[2];
    a_mid_2 = a2[0] * a3[1] - a2[1] * a3[0];
    return abs(float(a1[0] * a_mid_0 + a1[1] * a_mid_1 + a1[2] * a_mid_2));
}

"""
    Create a usable config from the wandb config format.

    Args:
        config: The config to convert.

    Returns:
        The converted config.
    """
def from_wandb_format(config: dict[str, object]) -> dict[str, object] {
    wandb_config: dict[str, object] = {};
    for (key, value) in config.items() {
        if '.' in key {
            sub_keys = key.split('.');
            curr_dict = wandb_config;
            for sub_key in sub_keys[:-1] {
                if sub_key not in curr_dict {
                    curr_dict[sub_key] = {};
                }
                curr_dict = curr_dict[sub_key];
            }
            if isinstance(value, dict) and 'value' in value {
                curr_dict[sub_keys[-1]] = value['value'];
            } else {
                curr_dict[sub_keys[-1]] = value;
            }
        } elif isinstance(value, dict) and 'value' in value {
            wandb_config[key] = value['value'];
        } else {
            wandb_config[key] = value;
        }
    }
    return wandb_config;
}

