    """
def create_confusion_matrix(row: dict[str, int]) -> str {
    if row['actual_label'] == 1 {
        if row['predicted_label'] == 1 {
            return 'TP';
        } else {
            return 'FN';
        }
    } elif row['predicted_label'] == 1 {
