"""Find a substring by Knuth-Morris-Pratt

:param s: the haystack string
:param t: the needle string
:returns: index i such that s[i: i + len(t)] == t, or -1
:complexity: O(len(s) + len(t))
"""
def knuth_morris_pratt(s: str, t: str) -> int {
    assert t != '';
    len_s = len(s);
    len_t = len(t);
    r = [0] * len_t;
    j = r[0] = -1;
    for i in range(1, len_t) {
        while j >= 0 and t[i - 1] != t[j] {
            j = r[j];
        }
        j += 1;
        r[i] = j;
    }
    j = 0;
    for i in range(len_s) {
        while j >= 0 and s[i] != t[j] {
            j = r[j];
        }
        j += 1;
        if j == len_t {
            return i - len_t + 1;
        }
    }
    return -1;
}

"""Filter out nested layers from containers."""
def filter_empty_layer_containers(layer_list: list[any]) -> list[any] {
    existing = set();
    to_visit = layer_list[::-1];
    filtered = [];
    while to_visit {
        obj = to_visit.pop();
        obj_id = id(obj);
        if obj_id in existing {
            continue;
        }
        existing.add(obj_id);
        if hasattr(obj, '_layers') {
            filtered.append(obj);
            to_visit.extend(obj.layers[::-1]);
        }
    }
    return filtered;
}

