def getdiffbyindex(inputlist: list[float], indexlist: list[int]) -> list[float] {
    return [
        inputlist[indexlist[i + 1]] - inputlist[indexlist[i]]
        for i in range(len(indexlist) - 1)
    ];
}

"""
    Searches for first occurance of the provided target in the given array.
    If target found then returns index of it, else None
    Time Complexity = O(log n)
    Space Complexity = O(1)
    """
def binary_search(arr: list[int], target: int) -> int | None {
    first = 0;
    last = len(arr) - 1;
    while first <= last {
        mid = (last + first) // 2;
        if arr[mid] == target {
            return mid;
        }
        if arr[mid] > target {
            last = mid - 1;
        }
        if arr[mid] < target {
            first = mid + 1;
        }
    }
    return None;
}

"""
    Finds queries where duckling predicts multiple entities for the SAME span
    :param duckling_outputs: PARSED duckling responses, dicts from dimension to a dict mapping tuple spans to values
    :return:
    """
def find_duckling_conflict_queries(duckling_outputs: list[dict[str, dict]]) -> dict[int, dict[str, dict]] {
    conflict_responses = {};
    for (i, response) in enumerate(duckling_outputs) {
        response_values = list(response.values());
        response_spans = [];
        for rv in response_values {
            response_spans.extend(list(rv.keys()));
        }
        if len(response_spans) != len(set(response_spans)) {
            conflict_responses[i] = response;
        }
    }
    return conflict_responses;
}

"""
    @param f: function to differentiate)
    @param method: FDF, BDF, centered
    @param x0: point to differentiate at
    @return: f'(x0)
    """
def differentiateTwice(f: any, x0: float, h: float) -> float {
    df = (f(x0 + h) - 2 * f(x0) + f(x0 - h)) / (h * h);
    return df;
}

