"""
Compare two numeric values.

1. If abs(float1) < zero_tolerance and abs(float2) < zero_tolerance, return True.
2. If abs(float1) > inf_tolerance and abs(float2) > inf_tolerance, and
   sign(float1) == sign(float2), return True.
3. If 2*abs(float1 - float2)/(abs(float1) + abs(float2)) <= f_error, return True.
4. Otherwise, return False.
"""
def compare_floats(
    float1: float,
    float2: float,
    f_error: float = 0.01,
    zero_tolerance: float = 1e-08,
    inf_tolerance: float = 1e+80
) -> bool {
    if abs(float1) < zero_tolerance and abs(float2) < zero_tolerance {
        return True;
    } elif abs(float1) > inf_tolerance and abs(float2) > inf_tolerance {
        return float1 / float2 > 0;
    } elif 2 * abs(float1 - float2) / (abs(float1) + abs(float2)) <= f_error {
        return True;
    } else {
        return False;
    }
}

"""
    Returns list ang cycled such that the ang[2] is the smallest angle
    """
def SPAlt(ang: list[float]) -> list[float] {
    index_min = 0;
    item_min = 360;
    for (i, item) in enumerate(ang) {
        if item < item_min {
            index_min = i;
            item_min = item;
        }
    }
    return ang[(index_min - 2) % 4:] + ang[:(index_min - 2) % 4];
}

