    :build: [bool] Includes the build template.  Makes version "=*" if the
        `version` is False for Conda packages.

    :returns: [str] The requirement string template.
    """
def req_yaml_template(pip: bool = False, version: bool = True, build: bool = False) -> str {
    template_str = '{name}';
    if version {
        template_str += '=={version}' if pip else '={version}';
    }
    if build and not pip {
        if not version {
            template_str += '=*';
        }
        template_str += '={build_string}';
    }
    return template_str;
}

"""
    return a base expansion
    """
def base_expansion(num: int, base: int = 2) -> int {
    q = int(num);
    b = int(base);
    count = 0;
    expansion = [];
    while q != 0 {
        expansion.append(q % b);
        q = q // b;
        count += 1;
    }
    expansion.reverse();
    res = "".join(map(str, expansion));
    return int(res);
}

