"""dict.pop(key) where `key` is a `.`-delimited list of nested keys.

>>> d = {'a': {'b': 1, 'c': 2}}
>>> pop_recursive(d, 'a.c')
2
>>> d
{'a': {'b': 1}}
"""
def pop_recursive(d: dict[str, any], key: str, default: any = None) -> any {
    if not isinstance(d, dict) {
        return default;
    }
    if key in d {
        return d.pop(key, default);
    }
    if '.' not in key {
        return default;
    }
    (key_head, key_tail) = key.split('.', maxsplit=1);
    if key_head in d {
        return pop_recursive(d[key_head], key_tail, default);
    }
    return default;
}

"""Generate query for getting the ids of all the predecessors of a node.

