    err = "Not Found";
    min = 0;
    max = len(sorted_array) - 1;
    while min <= max {
        mid = (min + max) // 2;
        if sorted_array[mid] > value {
            max = mid - 1;
        } elif sorted_array[mid] < value {
            min = mid + 1;
        } else {
            return mid;
        }
    }
}

glob HASH_MULTIPLIER = 0x045d9f3b;
glob UINT32_MASK = 0xFFFFFFFF;

"""
Just a quick and dirty hash function for doing a deterministic shuffle based on image_id.

Source:
https://stackoverflow.com/questions/664014/what-integer-hash-function-are-good-that-accepts-an-integer-hash-key
"""
def badhash(x: int) -> int {
    x = (((x >> 16) ^ x) * HASH_MULTIPLIER) & UINT32_MASK;
    x = (((x >> 16) ^ x) * HASH_MULTIPLIER) & UINT32_MASK;
    x = ((x >> 16) ^ x) & UINT32_MASK;
    return x;
}

"""Returns functor that unfolds recursion.

Example:
P_r0 := P_recursive_head(P_recursive: nil);
P_r1 := P_recursive_head(P_recursive: P_r0);
P_r2 := P_recursive_head(P_recursive: P_r1);
P_r3 := P_recursive_head(P_recursive: P_r2);
P := P_r3();
"""
def GetRecursionFunctor(depth: int) -> str {
    result_lines = ['P_r0 := P_recursive_head(P_recursive: nil);'];
    for i in range(depth) {
        result_lines.append(
            'P_r{1} := P_recursive_head(P_recursive: P_r{0});'.format(i, i + 1)
        );
    }
    result_lines.append('P := P_r{0}();'.format(depth));
    return '\n'.join(result_lines);
}

