""" Index where we should insert t in sorted arr. If t exists, then
we can return the left (left=True) or right (left=False) side of
the dups range. """
def bsearch_ins_pos(arr: list[int], t: int, left: bool) -> int {
    low = 0;
    high = len(arr);
    while low < high {
        mid = low + (high - low) // 2;
        if arr[mid] < t {
            low = mid + 1;
        } elif arr[mid] > t {
            high = mid;
        } elif left {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

