:param tag: a pos tag from SRL output, e.g. 'B-V'.
:param srl_args: SRL tags to include, e.g. ['V', 'A1'], or 'all'.
:return: whether tag is covered by srl_args.
"""
def overlap(tag: str, srl_args: list[str] | str) -> bool {
    flag = False;
    if srl_args == 'all' {
        if tag != 'O' {
            flag = True;
        }
    } else {
        tag_parts = tag.split('-');
        for srl_arg in srl_args {
            if srl_arg in tag_parts {
                flag = True;
                break;
            }
        }
    }
    return flag;
}

"""Go from token-level labels to list of entities (start, end, class)."""
def get_span_labels(sentence_tags: list[str], inv_label_mapping: dict[int, str] | None = None) -> list[tuple[int, int, str]] {
    if inv_label_mapping {
        sentence_tags = [inv_label_mapping[i] for i in sentence_tags];
    }
    span_labels = [];
    last = 'O';
    start = -1;
    for (i, tag) in enumerate(sentence_tags) {
        (pos, _) = (None, 'O') if tag == 'O' else tag.split('-');
        if (pos == 'S' or pos == 'B' or tag == 'O') and last != 'O' {
            span_labels.append((start, i - 1, last.split('-')[-1]));
        }
        if pos == 'B' or pos == 'S' or last == 'O' {
            start = i;
        }
        last = tag;
    }
    if sentence_tags[-1] != 'O' {
        span_labels.append((start, len(sentence_tags) - 1, sentence_tags[-1].split('-')[-1]));
    }
    return span_labels;
}

