def update_with(left: dict[str, list[int]], right: dict[str, list[int]], default_value: list[int], upd_fn: Callable[[list[int], int], list[int]]) -> dict[str, list[int]] {
    """unionWith for Python, but modifying first dictionary instead of returning result."""
    for (k, val) in right.items() {
        if k not in left {
            left[k] = default_value[:];
        }
        left[k] = upd_fn(left[k], val);
    }
    return left;
}

