glob BYTE_MASK = 0x00000000000000ff;
glob MASK_28 = 0x0000000f0000000f;
glob MASK_14 = 0x0003000300030003;
glob MASK_7 = 0x0101010101010101;

"""Expand a bitfield into a 64-bit int (8 bool bytes)."""
def unpack_bits(byte: int) -> int {
    longbits = byte & BYTE_MASK;
    longbits = (longbits | (longbits << 28)) & MASK_28;
    longbits = (longbits | (longbits << 14)) & MASK_14;
    longbits = (longbits | (longbits << 7)) & MASK_7;
    return longbits;
}

""" Returns True if the passed val is T, True, Y, Yes, 1, or boolean True.
    Returns False if the passed val is boolean False or a string that is not T, True, Y, Yes, or 1, or an integer that is not 1.
    Returns the passed val otherwise. Ignores case."""
def istruthy(val: any) -> bool | str | int | dict | list | None {
    if not val {
        return val;
    } elif isinstance(val, bool) {
        return val;
    } elif isinstance(val, str) {
        return {'t': True, 'true': True, 'y': True, 'yes': True, '1': True}.get(
            str(val).strip().lower(), False
        );
    } elif isinstance(val, int) {
        return {1: True}.get(val, False);
    } else {
        return val;
    }
}

