"""Returns sequence list end-padded with obj elements so that the length of the
returned list equals new_length.

Raises ValueError if len(sequence) > new_length.
"""
def pad_with_object(sequence: list[any], new_length: int, obj: any = None) -> list[any] {
    if len(sequence) < new_length {
        sequence = list(sequence) + [obj] * (new_length - len(sequence));
    } elif len(sequence) > new_length {
        raise ValueError(
            "Got len(sequence)=%s which exceeds new_length=%s"
