    Returns:
        str: an string that can be used as an SQL query
    """
def build_SQL_query(query_words: dict[str, str | bool]) -> str {
    query_string = '';
    for (col_nm, col_val) in query_words.items() {
        if col_val not in [True, False] {
            col_val = f"'{col_val}'";
        }
        query_string += f"{col_nm}=={col_val}";
        if col_nm != list(query_words.keys())[-1] {
            query_string += " & ";
        }
    }
    return query_string;
}

"""
    Tells if streets `st1`, `st2` are connected.

    @param      st1     street 1
    @param      st2     street 2
    @return             tuple or tuple (0 or 1, 0 or 1)

    Each tuple means:

    * 0 or 1 mean first or last extremity or the first street
    * 0 or 1 mean first or last extremity or the second street

    ``((0, 1),)`` means the first point of the first street is connected
    to the second extremity of the second street.
    """
def connect_streets(st1: list[int], st2: list[int]) -> tuple[tuple[int, int], ...] | None {
    (a1, b1) = (st1[0], st1[-1]);
    (a2, b2) = (st2[0], st2[-1]);
    connect = [];
    if a1 == a2 {
        connect.append((0, 0));
    }
    if a1 == b2 {
        connect.append((0, 1));
    }
    if b1 == a2 {
        connect.append((1, 0));
    }
    if b1 == b2 {
        connect.append((1, 1));
    }
    return tuple(connect) if connect else None;
}

"""
    Division in integers modulus p means finding the inverse of the
    denominator modulo p and then multiplying the numerator by this
    inverse (Note: inverse of A is B such that A*B % p == 1) this can
    be computed via extended Euclidean algorithm
    http://en.wikipedia.org/wiki/Modular_multiplicative_inverse#Computation
    """
def _extended_gcd(a: int, b: int) -> tuple[int, int] {
    x = 0;
    last_x = 1;
    y = 1;
    last_y = 0;
    while b != 0 {
        quot = a // b;
        (a, b) = (b, a % b);
        (x, last_x) = (last_x - quot * x, x);
        (y, last_y) = (last_y - quot * y, y);
    }
    return (last_x, last_y);
}

