"""Prepare filters (kwargs{}) for django queryset
    where fields contain digits are checked like = | > | >= | < | <=

    >>> mongodb_int_filter(10, '1')
    10.0
    >>> mongodb_int_filter(10, '2')
    {'$gt': 10.0}
    >>> mongodb_int_filter(10, '3')
    {'$gte': 10.0}
    >>> mongodb_int_filter(10, '4')
    {'$lt': 10.0}
    """
def mongodb_int_filter(base_field: int | float | str, base_field_type: str) -> float | dict | str {
    q: float | dict | str = '';
    if base_field != '' {
        if base_field_type == '1' {
            q = float(base_field);
        }
        if base_field_type == '2' {
            q = {'$gt': float(base_field)};
        }
        if base_field_type == '3' {
            q = {'$gte': float(base_field)};
        }
        if base_field_type == '4' {
            q = {'$lt': float(base_field)};
        }
        if base_field_type == '5' {
            q = {'$lte': float(base_field)};
        }
    }
    return q;
}

"""Calculate the median of a list."""
def median(data: list[float]) -> float {
    data.sort();
    num_values = len(data);
    half = num_values // 2;
    if num_values % 2 {
        return data[half];
    }
    return 0.5 * (data[half - 1] + data[half]);
}

import from typing { Iterator }

"""Read variable length encoded 128 bits signed integer.

    .. doctest::

        >>> from ppci.utils.leb128 import signed_leb128_decode
        >>> signed_leb128_decode(iter(bytes([0x9b, 0xf1, 0x59])))
        -624485
    """
def signed_leb128_decode(data: Iterator[int]) -> int {
    result = 0;
    shift = 0;
    while True {
        byte = next(data);
        result |= (byte & 0x7F) << shift;
        shift += 7;
        if byte & 0x80 == 0 {
            break;
        }
    }
    if byte & 0x40 {
        mask = (1 << shift) - 1;
        result = result ^ mask;
        result = -result - 1;
    }
    return result;
}

