def merge_sort2(lst: list[int]) -> list[int] {
    if len(lst) <= 1 {
        return lst;
    }
    def merge(left: list[int], right: list[int]) -> list[int] {
        x = 0;
        y = 0;
        z_list = [];
        while len(left) > x and len(right) > y {
            if left[x] > right[y] {
                z_list.append(right[y]);
                y += 1;
            } else {
                z_list.append(left[x]);
                x += 1;
            }
        }
        if len(left) != x {
            z_list += left[x - len(left) - 1:];
        }
        if len(right) != y {
            z_list += right[x - len(right) - 1:];
        }
        return z_list;
    }
    middle = int(len(lst) // 2);
    left = merge_sort2(lst[:middle]);
    right = merge_sort2(lst[middle:]);
    return merge(left, right);
}

"""
Write a function to compute the fibonacci sequence value to the requested iteration.

>>> solution(3)
2
>>> solution(10)
55
>>> solution(20)
6765
"""
def solution(number: int) -> int {
    m = {0: 0, 1: 1};
    for i in range(2, number + 1) {
        m[i] = m[i - 1] + m[i - 2];
    }
    return m[number];
}

"""
Naive implementation of a primality test. Adapted from:
https://en.wikipedia.org/wiki/Primality_test#Pseudocode
"""
def is_prime(n: int) -> bool {
    if n <= 1 {
        return False;
    } elif n <= 3 {
        return True;
    } elif n % 2 == 0 or n % 3 == 0 {
        return False;
    }
    i = 5;
    while i * i <= n {
        if n % i == 0 or n % (i + 2) == 0 {
            return False;
        }
        i += 6;
    }
    return True;
}

"""Computes x, y such that gcd(a,b) = ax + by"""
def egcd(a: int, b: int) -> tuple[int, int] {
    if not b {
        return (1, 0);
    }
    (x, y) = egcd(b, a % b);
    return (y, x - (a // b) * y);
}

