"""
    Now, the jumps are even stranger: after each jump, if the offset was three or more,
    instead decrease it by 1. Otherwise, increase it by 1 as before.

    Using this rule with the above example, the process now takes 10 steps,
    and the offset values after finding the exit are left as 2 3 2 3 -1.

    How many steps does it now take to reach the exit?
    """
def part2(input_lines: list[str]) -> int {
    jumps = [int(line) for line in input_lines];
    def jump(at: int) -> int {
        to = at + jumps[at];
        if jumps[at] > 2 {
            jumps[at] -= 1;
        } else {
            jumps[at] += 1;
        }
        return to;
    }
    pos = 0;
    count = 0;
    while pos >= 0 and pos < len(jumps) {
        count += 1;
        pos = jump(pos);
    }
    return count;
}

"""Solve a dependency graph.

    Parameters
    ----------
    dependencies : dict
        For each key, the value is an iterable indicating its dependencies.
    all_members : iterable, optional
        List of all keys in the graph.
        Useful to guarantee that all keys will be in the result even
        if they are disconnected from the graph.
        (Default value: empty)

    Returns
    -------
    list of sets
        Each set contains tasks that depend only on the tasks
        in the previous set in the list.

    """
def solve_dependencies(dependencies: dict[str, list[str]], all_members: list[str] | None = None) -> list[set]:
def solve_dependencies(dependencies: dict[str, list[str]], all_members: list[str] | None = None) -> list[set] {
    d = dict((key, set(value)) for (key, value) in dependencies.items());
    if all_members {
        d.update(
            {
                key: set()
                for key in all_members
                if key not in d
            }
        );
    }
    r = [];
    while d {
        t = set(i for v in d.values() for i in v) - set(d.keys());
        t.update(
            k
            for (k, v) in d.items()
            if not v
        );
        r.append(t);
        d = dict(
            (k, v - t)
            for (k, v) in d.items()
            if v
        );
    }
    return r;
}

