"""Checks if colors are similar.

    :param tuple[int, int, int] color1: original color.
    :param tuple[int, int, int] color2: color to check.
    :param float overlap: overlap parameter. If colors similarity > overlap then colors are similar.

    :rtype: bool
    """
def is_color_similar(color1: tuple[int, int, int], color2: tuple[int, int, int], overlap: float = 0.05) -> bool {
    (r1, g1, b1) = color1;
    (r2, g2, b2) = color2;
    d = ((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2) ** (1 / 2.0);
    return d / 510 <= overlap;
}

"""
    Update ``P`` such that for the updated `P'` `P' v = e_{s}`.
    """
def _update(s: int, _lambda: list[float], P: list[list[float]]) -> list[list[float]] {
    k = min([j for j in range(s, len(_lambda)) if _lambda[j] != 0]);
    for r in range(len(_lambda)) {
        if r != k {
            P[r] = [P[r][j] - (P[k][j] * _lambda[r]) / _lambda[k] for j in range(len(P[r]))];
        }
    }
    P[k] = [P[k][j] / _lambda[k] for j in range(len(P[k]))];
    (P[k], P[s]) = (P[s], P[k]);
    return P;
}

