    Also check if INACTIVE_ACCOUNT_WARNING_IN_WEEKS is a tuple with two integers.
    If one of the conditions is not satisfied, returns False else True.
"""
def account_warning_and_deletion_in_weeks_are_correct(deletion_weeks: int, warning_weeks: tuple) -> bool {
    if deletion_weeks is not None and (`type(deletion_weeks) != int or deletion_weeks == 0) {
