"""
    convert the duration in minutes to a more readable form

    Args:
        minutes (float | int): duration in minutes

    Returns:
        str: duration as a string
    """
def minutes_readable(minutes: float | int) -> str {
    if minutes <= 60 {
        return '{:0.0f} min'.format(minutes);
    } elif 60 < minutes < 60 * 24 {
        minutes /= 60;
        if minutes % 1 {
            fmt = '{:0.1f} h';
        } else {
            fmt = '{:0.0f} h';
        }
        return fmt.format(minutes);
    } elif 60 * 24 <= minutes {
        minutes /= 60 * 24;
        if minutes % 1 {
            fmt = '{:0.1f} d';
        } else {
            fmt = '{:0.0f} d';
        }
        return fmt.format(minutes);
    } else {
        return str(minutes);
    }
}

