"""
def validipaddr(address: str) -> bool {
    try {
        octets = address.split(".");
        if len(octets) != 4 {
            return False;
        }
        for x in octets {
            if " " in x {
                return False;
            }
            if not (0 <= int(x) <= 255) {
                return False;
            }
        }
    } except ValueError {
        return False;
    }
    return True;
}

"""
Function that converts a board (in FEN notation) in a list of lists of lines of the chess board
Parameters :
    -board : the current board
Returns :
    -arrayBoard : a list composed of lists(=lines) of the strings(=pieces)  of the boards
"""
def boardToArray(board: str) -> list[list[str]] {
    board = board.replace("1", "-").replace("2", "--").replace("3", "---").replace(
        "4", "----"
    ).replace(
        "5", "-----"
    ).replace(
        "6", "------"
    ).replace(
        "7", "-------"
    ).replace(
        "8", "--------"
    );
    current_line: list[str] = [];
    list_board: list[list[str]] = [];
    for (i, char) in enumerate(board) {
        if char == ' ' {
            list_board.append(current_line);
            break;
        }
        if (i + 1) % 9 == 0 {
            list_board.append(current_line);
            current_line = [];
        } else {
            current_line.append(char);
        }
    }
    return list_board;
}

