        "http":{
            "hostname":"supportingfunctions.us.newsweaver.com",
            "http_port":443
            }
    }

    will be converted to

    {
        "event_type":"http",
        "http.hostname":"supportingfunctions.us.newsweaver.com",
        "http.http_port":443
    }
    """
def modify_eve_dict(eve_dict: dict) -> dict {
    modified = {};

    """
        Recursive function to flatten the nested dictionaries.
        """;
    def flatten(x: dict | list | str | int | float | bool | None, name: str = '') -> None {
        if `type(x) is dict {
            for val in x {
                flatten(x[val], name + val + '.');
            }
        } elif `type(x) is list {
            i = 0;
            for val in x {
                name = name.rstrip('.');
                flatten(val, name + '[' + str(i) + ']' + '.');
                i += 1;
            }
        } elif name[:-1] not in ["flow.start", "flow.end"] {
            modified[name[:-1]] = x;
        }
    }
    flatten(eve_dict);
    return modified;
}

"""Converts a number of seconds to a human-readable time in seconds, minutes, and hours."""
def readable_time(seconds: int | float) -> str {
    parts: list[str] = [];
    if seconds >= 86400 {
        days = seconds // 86400;
        if days == 1 {
            parts.append("{} day".format(int(days)));
        } else {
            parts.append("{} days".format(int(days)));
        }
    }
    if seconds >= 3600 {
        hours = (seconds // 3600) % 24;
        if hours == 1 {
            parts.append("{} hour".format(int(hours)));
        } else {
            parts.append("{} hours".format(int(hours)));
        }
    }
    if seconds >= 60 {
        minutes = (seconds // 60) % 60;
        if minutes == 1 {
            parts.append("{} minute".format(int(minutes)));
        } else {
            parts.append("{} minutes".format(int(minutes)));
        }
    }
    seconds = round(seconds % 60, 2);
    if seconds == 1 {
        parts.append("{} second".format(seconds));
    } else {
        parts.append("{} seconds".format(seconds));
    }
    return ", ".join(parts);
}

