"""
Function to add two dictionaries by adding lists of matching keys
:param parent_dict: The Dict to which the second dict should be merged with
:param merge_dict: Dict to be merge with the parent

:return: Dict having the two inputs merged
"""
def merge_dicts_lists(parent_dict: dict[any, any], merge_dict: dict[any, any]) -> dict[any, any] {
    for key in merge_dict.keys() {
        if key in parent_dict {
            if not isinstance(merge_dict[key], list) {
                parent_dict[key] += [merge_dict[key]];
            } else {
                parent_dict[key] += merge_dict[key];
            }
        } elif not isinstance(merge_dict[key], list) {
            parent_dict[key] = [merge_dict[key]];
        } else {
            parent_dict[key] = merge_dict[key];
        }
    }
    return parent_dict;
}

""" Binary Search takes array and value to search """
def binary_search(arr: list[int], value: int) -> int {
    """ returns index or-1""";
    count = len(arr);
    midpoint = count // 2;
    start_index = 0;
    end_index = count - 1;
    while value != arr[start_index + midpoint] and count > 1 {
        if value > arr[midpoint + start_index] {
            start_index = midpoint;
            count = count - midpoint;
            midpoint = count // 2;
        } else {
            end_index = end_index - midpoint;
            count = count - midpoint;
            midpoint = count // 2;
        }
    }
    if value == arr[midpoint + start_index] {
        return midpoint + start_index;
    } else {
        return -1;
    }
}

