"""
      :args g: Unpermuted groups
      :args gp: Permuted groups.
      :args perm: Permuted of gp.
    """
def _find_permutation_of_group(g: list, gp: list) -> list[int] {
    n = len(g);
    perm = [];
    skip = [False for i in range(n)];
    for im in range(n) {
        for jm in range(n) {
            if skip[jm] {
                continue;
            }
            if gp[jm] == g[im] {
                perm.append(jm);
                skip[jm] = True;
                break;
            }
        }
    }
    return perm;
}

