"""Generate paths to examine from a variable-type template.

    `template` may be a str, list of str, or dict; when a dict, `lookup_key`
    selects which value to treat as the new template (or all values if None).
    """
def _expand_check_paths(template: str | list[str] | dict[str, str | list[str]], lookup_key: str | None) -> list[str] {
    check_paths = [];
    if isinstance(template, `dict) {
        if lookup_key is None {
            check_paths += _expand_check_paths(`list(template.values()), lookup_key);
        } else {
            check_paths += _expand_check_paths(template.get(lookup_key, []), lookup_key);
        }
    } elif isinstance(template, `list) {
        for value in template {
            check_paths += _expand_check_paths(value, lookup_key);
        }
    } else {
        check_paths += [template];
    }
    return check_paths;
}

