"""Calculates a barycenter from an interconnectivity vector (1 = connection, 0 = no connection)."""
def get_barycenter(vector: list[int]) -> int | float {
    (weighted_sum, sum) = (0, 0);
    for x in range(len(vector)) {
        if vector[x] {
            weighted_sum += x + 1;
            sum += 1;
        }
    }
    if sum == 0 {
        return -1;
    } else {
        return weighted_sum / sum;
    }
}

"""
Writes the basis function term with the given index.
"""
def writeTerm(index: int) -> str {
    global coeffs;
    coeffs = [];
    eqtn = "";
    term_index = 0;
    for i in range(1, 9) {
        for j in range(1, 13) {
            term_index += 1;
            coeffs.append([i, j / 8.0, 0]);
            if index == term_index {
                eqtn = eqtn + " %s^%d * %s^%.3f" % ("D", i, "T", j / 8.0);
            }
        }
    }
    for i in range(1, 6) {
        for j in range(1, 24) {
            term_index += 1;
            coeffs.append([i, j / 8.0, 1]);
            if index == term_index {
                eqtn = eqtn + " %s^%d * %s^%.3f * exp(-D^1)" % ("D", i, "T", j / 8.0);
            }
        }
    }
    for i in range(1, 6) {
        for j in range(1, 30) {
            term_index += 1;
            coeffs.append([i, j / 8.0, 2]);
            if index == term_index {
                eqtn = eqtn + " %s^%d * %s^%.3f * exp(-D^2)" % ("D", i, "T", j / 8.0);
            }
        }
    }
    for i in range(2, 5) {
        for j in range(24, 38) {
            term_index += 1;
            coeffs.append([i, j / 2.0, 3]);
            if index == term_index {
                eqtn = eqtn + " %s^%d * %s^%.3f * exp(-D^3)" % ("D", i, "T", j / 8.0);
            }
        }
    }
    return eqtn;
}

"""Get mongo query filter by recursion.

key_condictions is a list of (key, value, direction) tuples.

>>> generate_spec([
...     ('a', '10', 1),
...     ('b', '20', 0),
... ])
{'$or': [{'$and': [{'a': '10'}, {'b': {'$lt': '20'}}]}, {'a': {'$gt': '10'}}]}
"""
def generate_spec(key_condictions: list[tuple[str, str, int]]) -> dict[str, object] {
    if not key_condictions {
        return {};
    }
    (key, value, direction) = key_condictions[0];
    gt_or_lt = '$gt' if direction == 1 else '$lt';
    next_ordering = generate_spec(key_condictions[1:]);
    if next_ordering {
        return {
            '$or': [{'$and': [{key: value}, next_ordering]}, {key: {gt_or_lt: value}}]
        };
    } else {
        return {key: {gt_or_lt: value}};
    }
}

"""Check test conditions in scenario results input.

Check whether the input parameters of a behave scenario results record from
testapi match the input parameters of the latest test. In other words,
check that the test results from testapi come from a test done under the
same conditions (frame size, flow count, rate, ...).

Args:
    input: input dict of a results dict of a behave scenario from testapi
    result: dict of nfvbench params used during the last test

Returns:
    True if test conditions match, else False.
"""
def get_result_from_input_values(input: dict[str, object], result: dict[str, object]) -> bool {
    required_keys = ['duration_sec', 'frame_sizes', 'flow_count', 'rate'];
    if 'user_label' in result {
        required_keys.append('user_label');
    }
    if 'flavor_type' in result {
        required_keys.append('flavor_type');
    }
    subset_input = dict((k, input[k]) for k in required_keys if k in input);
    subset_result = dict((k, result[k]) for k in required_keys if k in result);
    return subset_input == subset_result;
}

