"""
Convert milliseconds into a string in format mm:ss.ms.
"""
def from_ms(time: int) -> str {
    minute = time // 60000;
    second = time // 1000 - minute * 60;
    millisecond = time - minute * 60000 - second * 1000;
    second_str = "0" + str(second) if second < 10 else str(second);
    if millisecond < 10 {
        millisecond_str = f"00{millisecond}";
    } elif millisecond < 100 {
        millisecond_str = f"0{millisecond}";
    } else {
        millisecond_str = str(millisecond);
    }
    return f"{minute}:{second_str}.{millisecond_str}";
}

