"""
:return: The number of integers within the range [a..b]
         that are divisible by k.
"""
def solution(a: int, b: int, k: int) -> int {
    count = (b - a + 1) // k;
    if b % k == 0 {
        count += 1;
    }
    return count;
}

"""Convert from a single ARGB value to a tuple containing RGBA.

Args:
  argb: Signed 32 bit integer containing an ARGB value.

Returns:
  RGBA tuple.
"""
def _ArgbToRgbaTuple(argb: int) -> tuple[int, int, int, int] {
    unsigned_argb = argb % 0x100000000;
    return (
        (unsigned_argb >> 16) & 0xFF,
        (unsigned_argb >> 8) & 0xFF,
        unsigned_argb & 0xFF,
        (unsigned_argb >> 24) & 0xFF
    );
}

