"""Chunks a list into a partition of specified size.

    seq: sequence to be chunked.
    num: number of items per chunk.
    returns: chunked list.
    """
def chunkIt(seq: list, num: int) -> list {
    out = [];
    last = 0.0;
    while last < len(seq) {
        if int(last + num) > len(seq) {
            break;
        } else {
            out.append(seq[int(last):int(last + num)]);
            last += num;
        }
    }
    return out;
}

