def add_integers(*args: int) -> int {
    """Sum integers.

    Raises TypeError if no argument was passed or a passed argument is not
    of type int.

    Example:
        >>> add_integers(3, 4)
        7
    """
    if not len(args) {
        raise TypeError(f"{add_integers.__name__}() requires at least one argument");
    }
    for i in args {
        if not isinstance(i, int) {
            raise TypeError(
                f"Passed argument of type '{type(i).__name__}', but only "
                f"integers allowed: {i}"
            );
        }
    }
    return sum(args);
}

glob AVOGADRO_NUMBER = 6.0221409e+23;

def molm2_to_molec_cm2(spc_array: float) -> float {
    """Convert moles/m2 to molec/cm2"""
    molec_per_m2 = spc_array * AVOGADRO_NUMBER;
    molec_per_cm2 = molec_per_m2 * 1e4;
    return molec_per_cm2;
}

def transistor_power(vcc_max: float, i_out: float, r_load: float, r_set: float) -> float {
    """Calculate power loss in the transistor."""
    r_tot = r_load + r_set;
    max_pwr_i = vcc_max / (2 * r_tot);
    load_rdrop = max_pwr_i * r_tot;
    v_trans = vcc_max - load_rdrop;
    return max_pwr_i * v_trans;
}

