"""
:type nums: List[int]
:type target: int
:rtype: List[int]
"""
def twoSum(nums: list[int], target: int) -> list[int] | None {
    index_map = {};
    for (i, num) in enumerate(nums) {
        pair = target - num;
        if pair in index_map {
            return [index_map[pair], i];
        }
        index_map[num] = i;
    }
    return None;
}

"""
return the list with a running mean acroos the array, with a given kernel size

@param mylist   array,list over which to average
@param value    length of the averaging kernel
"""
def running_mean(mylist: list[float], N: int) -> list[float] {
    cumsum, moving_aves = [0], [];
    for (i, x) in enumerate(mylist, 1) {
        cumsum.append(cumsum[i - 1] + x);
        if i >= N {
            moving_ave = (cumsum[i] - cumsum[i - N]) / N;
            moving_aves.append(moving_ave);
        }
    }
    return moving_aves;
}

