"""Partition helper function for quicksort."""
def partition(lst: list[int], start: int, end: int) -> int {
    sorted = False;
    pivot = lst[start];
    left = start + 1;
    right = end;
    while not sorted {
        while left <= right and lst[left] <= pivot {
            left = left + 1;
        }
        while lst[right] >= pivot and right >= left {
            right = right - 1;
        }
        if right < left {
            sorted = True;
        } else {
            temp = lst[left];
            lst[left] = lst[right];
            lst[right] = temp;
        }
    }
    temp = lst[start];
    lst[start] = lst[right];
    lst[right] = temp;
    return right;
}

