"""
	Docstring for function pyKrev.element_counts
	====================
	This function takes a list of formula strings and gives atomic counts for C,H,N,O,P & S.

	Use
	----
	element_counts(Y)

	Returns a list of len(Y) in which each element is a dictionary containing the atomic counts.

	Parameters
	----------

	Y: A list of elemental formula strings. All integers must be standard script (e.g. C6H8O7).
       The list should not contain isotopologues (e.g. C9H12O6 13C1) and should only contain C,H,N,O,P and S atoms.

    """
def element_counts(formula_list: list[str]) -> list[dict[str, int]] {
    elements = ['C', 'H', 'N', 'O', 'P', 'S'];
    count_list = [];
    for formula in formula_list {
        element_numbers: dict[str, int] = {};
        for element in elements {
            element_numbers[element] = 0;
            alpha_idx = formula.find(element);
            if alpha_idx > -1 {
                element_numbers[element] = 1;
                for i in range(alpha_idx + 2, len(formula) + 1) {
                    try {
                        element_numbers[element] = int(formula[alpha_idx + 1:i]);
                    } except ValueError {
                        break;
                    }
                }
            }
        }
        count_list.append(element_numbers);
    }
    return count_list;
}

"""Returns a dictionary of subsystems to their cgroup.

    Arguments:
      cgroup_info: An iterable where each item is a line of a cgroup file.

    """
def _parse_cgroup_ids(cgroup_info: list[str]) -> dict[str, str] {
    cgroup_ids: dict[str, str] = {};
    for line in cgroup_info {
        parts = line.split(':');
        if len(parts) != 3 {
            continue;
        }
        (_, subsystems, cgroup_id) = parts;
        subsystems = subsystems.split(',');
        for subsystem in subsystems {
            cgroup_ids[subsystem] = cgroup_id;
        }
    }
    return cgroup_ids;
}

