    return d + m / 60.0 + s / 3600.0;
}

"""Pretty-print a number of bytes."""
def _FormatBytes(byts: float) -> str {
    if byts > 2 ** 20.0 {
        byts /= 2 ** 20.0;
        return '%.2fm' % byts;
    }
    if byts > 2 ** 10.0 {
        byts /= 2 ** 10.0;
        return '%.2fk' % byts;
    }
    return str(byts);
}

"""
    program com um funcao fatorial, que recebe um numero como parametro e retorna o fatorial
    Com um parametro opcional se ele receber True mostra a operacao
    """
def fatorial(num: int, show: bool = False) -> int {
    print('-=' * 30);
    fat = 1;
    for c in range(num, 0, -1) {
        if show {
            print(c, end='');
            if c > 1 {
                print(f' x ', end='');
            } else {
                print(' = ', end='');
            }
        }
        fat *= c;
    }
    return fat;
}

"""
    Returns a list of chunks containing at most ``chunksize`` elements of data.
    """
def chunked(data: list[int], chunksize: int) -> list[list[int]] {
    if chunksize < 1 {
        raise ValueError("Chunksize must be at least 1!");
    }
    if int(chunksize) != chunksize {
        raise ValueError("Chunksize needs to be an integer");
    }
    res = [];
    cur = [];
    for e in data {
        cur.append(e);
        if len(cur) >= chunksize {
            res.append(cur);
            cur = [];
        }
    }
    if cur {
        res.append(cur);
    }
    return res;
}

"""Convert bytes to MB.... GB... etc."""
def convert_bytes(num: float) -> str | None {
    for x in ["bytes", "KB", "MB", "GB", "TB"] {
        if num < 1024.0 {
            return "%3.1f %s" % (num, x);
        }
        num /= 1024.0;
    }
}

