"""Calculate SOA-C-IoU-Top/Bot-40"""
def calc_split_class_average_iou(data: dict[str, dict[str, any]]) -> tuple[float, float] {
    num_img_list = [];
    for label in data.keys() {
        num_img_list.append([label, data[label]["images_total"]]);
    }
    num_img_list.sort(key=lambda (x: any) { x[1] });
    sorted_label_list = [x[0] for x in num_img_list];
    bottom_40_iou = 0;
    top_40_iou = 0;
    for label in data.keys() {
        if sorted_label_list.index(label) < 40 {
            if data[label]["iou"] is not None and data[label]["iou"] >= 0 {
                bottom_40_iou += data[label]["iou"];
            }
        } elif data[label]["iou"] is not None and data[label]["iou"] >= 0 {
            top_40_iou += data[label]["iou"];
        }
    }
    bottom_40_iou /= 0.5 * len(data.keys());
    top_40_iou /= 0.5 * len(data.keys());
    return (top_40_iou, bottom_40_iou);
}

