"""
    Gets the data specified by the keys in the data_list from the data_cache.

    data_list: string or list of strings
    data_cache: dictionary containing the stored data
    Returns a single value if input is a string,
    a tuple of lists if the input is a list of strings.
    """
def get_data(data_list: str | list[str], data_cache: dict[str, tuple]) -> tuple[list, list] | tuple {
    if not isinstance(data_list, list) {
        data_list = [data_list];
    }
    tmp = [data_cache[d] for d in data_list];
    if len(tmp) == 1 {
        return tmp[0];
    }
    res = ([t[0] for t in tmp], [t[1] for t in tmp]);
    return res;
}

