"""
    Removes duplicates from a list. Elements are ordered by the original
    order of their first occurrences.

    In terms of Python 2.4 and later, this is equivalent to list(set(a)).
    """
def uniq(a: list) -> list {
    if len(a) == 0 {
        return [];
    } else {
        return [a[0]] + uniq([x for x in a if x != a[0]]);
    }
}

"""
    This function take a number and a list of
    prime number (supposed to go farter than nb)
    and give the different prime numbers involved in
    the prime decomposition of the number.
    """
def unique_decompo_prime_factors(nb: int, l_nb_p: list[int]) -> list[int] {
    decompo = [];
    for elt in l_nb_p {
        if nb % elt == 0 {
            decompo.append(elt);
        }
    }
    return decompo;
}

