""" Returns query for eventsource (service) / actions performed by user. """
def services_by_user(
    account: str, days_back: int, user_arn: str, user_name: str
) -> tuple[str, str] {
    query_string = f"""SELECT DISTINCT eventsource, eventname FROM behold
        WHERE account = '{account}'
        AND (useridentity.arn = '{user_arn}')
        AND from_iso8601_timestamp(eventtime) > date_add('day', -{days_back}, now())
        ORDER BY eventsource, eventname;""";
    return (query_string, f"athena_results/services_by_user/{account}/{user_name}");
}

"""Return the median value of `sorted_seq`.

    >>> median ([1, 2, 2, 3, 14])
    2

    >>> median ([1, 2, 2, 3, 3, 14])
    2.5

    """
def median_s(sorted_seq: list[int | float]) -> int | float {
    l = len(sorted_seq);
    if l % 2 {
        result = sorted_seq[l // 2];
    } else {
        l -= 1;
        result = (sorted_seq[l // 2] + sorted_seq[l // 2 + 1]) / 2.0;
    }
    return result;
}

