"""Return the edit distance between two strings."""
def getEditDistance(str1: str, str2: str) -> int {
    if len(str1) == 0 {
        return len(str2);
    }
    if len(str2) == 0 {
        return len(str1);
    }
    matrix = [[i for k in range(len(str2) + 1)] for i in range(len(str1) + 1)];
    for i in range(len(str2) + 1) {
        matrix[0][i] = i;
    }
    for i in range(len(str2)) {
        for j in range(len(str1)) {
            if str2[i] == str1[j] {
                matrix[j + 1][i + 1] = matrix[j][i];
            } else {
                matrix[j + 1][i + 1] = min(
                    matrix[j][i + 1] + 1,
                    matrix[j + 1][i] + 1,
                    matrix[j][i] + 1
                );
            }
        }
    }
    return matrix[-1][-1];
}

"""Overload of list_pop that executes a Python list append."""
def _py_list_pop(list_: list, i: int | None) -> tuple {
    if i is None {
        x = list_.pop();
    } else {
        x = list_.pop(i);
    }
    return (list_, x);
}

"""
     - Name: TempMin -Version: 1.0, -Time step: 1
     - Description: recalculation of minimum temperature based on snow depth insulation.
     - Reference: doi:http://dx.doi.org/10.1016/j.agrformet.2014.05.002
    """
def model_tempmin(
    Sdepth_cm: float = 0.0,
    prof: float = 0.0,
    tmin: float = 0.0,
    tminseuil: float = 0.0,
    tmaxseuil: float = 0.0
) -> float {
    tminrec = tmin;
    if Sdepth_cm > prof {
        if tmin < tminseuil {
            tminrec = tminseuil;
        } elif tmin > tmaxseuil {
            tminrec = tmaxseuil;
        }
    } elif Sdepth_cm > 0.0 {
        tminrec = tminseuil - (1 - (Sdepth_cm / prof)) * (abs(tmin) + tminseuil);
    }
    return tminrec;
}

