"""Returns the lowest common multiple of two given integers."""
def lcm(num1: int, num2: int) -> int {
    temp_num = num1;
    while temp_num % num2 != 0 {
        temp_num += num1;
    }
    return temp_num;
}

glob BYTE0_MASK = 0xFF;
glob BYTE1_MASK = 0xFF00;
glob BYTE2_MASK = 0xFF0000;

""" Convert the hex representation of the number to a correctly ordered
    string.

    Parameters
    ----------
    val: int
        The integer representing the string. This is in reverse order.
        Ie. XXYYZZ -> chr(ZZ)chr(YY)chr(XX)

    Returns
    -------
    str
        The actual string.
    """
def hex_to_chars(num: int) -> str {
    return chr(num & BYTE0_MASK) + chr((num & BYTE1_MASK) >> 8) + chr((num & BYTE2_MASK) >> 16);
}

"""convert a sequence of embedded sequences into a plain list"""
def flatten_seq(seq: dict | list) -> list {
    result = [];
    vals = seq.values() if isinstance(seq, dict) else seq;
    for i in vals {
