    index_j (int): Column index.
    tile_arrangement (list[list[str]]): Arrangement of the tiles as a 2D grid.

Returns:
    bool: Whether or not the tile is occupied.
"""
def is_occupied(index_i: int, index_j: int, tile_arrangement: list[list[str]]) -> bool {
    if not (0 <= index_i <= len(tile_arrangement) - 1) {
        raise IndexError;
    }
    if not (0 <= index_j <= len(tile_arrangement[0]) - 1) {
        raise IndexError;
    }
    if tile_arrangement[index_i][index_j] == "#" {
        return True;
    } else {
        return False;
    }
}

