}

"""Truncates text and adds ellipses at the end. Does not truncate words in the middle."""
def ellipsis_after(text: str, length: int) -> str {
    if not text or len(text) <= length {
        return text;
    } else {
        return text[:length].rsplit(' ', 1)[0] + "…";
    }
}

"""
Return min and max digital values for each format type.

Parameters
---------
fmt : str, list
    The WFDB dat format, or a list of them.

Returns
-------
tuple (int, int)
    The min and max WFDB digital value per format type.
"""
def _digi_bounds(fmt: str | list[str]) -> tuple[int, int] | list[tuple[int, int]] | None {
    if isinstance(fmt, list) {
        return [_digi_bounds(f) for f in fmt];
    }
    match fmt {
        case '80':
            return (-128, 127);
        case '212':
            return (-2048, 2047);
        case '16':
            return (-32768, 32767);
        case '24':
            return (-8388608, 8388607);
        case '32':
            return (-2147483648, 2147483647);
    }
}

"""
Parameters:
-----------
m3: int
dl: list of int
Return:
-------
vol_m3: float
   volume in m3 from the dial and gauges values
   The nature of gauges means the gauge will show the next value early;
   converting requires taking 1 away from digit if digit for smaller gauge is 9.

   Example: reading gauges in order 2* 1/10 m3 + 9 *1/100 m3 = 0.19m3
"""
def meter_reading(m3: float, dl: list[int]) -> float {
    dl = [str(x[0] if x[1] < 9 else x[0] - 1) for x in zip(dl, dl[1:] + [0])];
    dl = int("".join(dl)) / (10 ** len(dl));
    return m3 + dl;
}

