"""Pythagorean Distance Equation.
    Function for counting distance,
    derived from the Pythagorean theorem.
    """
def pythagorean_distance_equation(path1: tuple[float, float], path2: tuple[float, float]) -> float {
    dot_x1 = path1[0];
    dot_x2 = path2[0];
    dot_y1 = path1[1];
    dot_y2 = path2[1];
    result_distance = ((dot_x2 - dot_x1) ** 2 + (dot_y2 - dot_y1) ** 2) ** 0.5;
    return result_distance;
}

