"""Removes the name prefix in checkpoint.

    Basically, when the model is deployed in parallel, the prefix `module.` will
    be added to the saved checkpoint. This function is used to remove the
    prefix, which is friendly to checkpoint loading.

    Args:
        state_dict: The state dict where the variable names are processed.
        prefix: The prefix to remove. (default: `module.`)
    """
def _strip_state_dict_prefix(state_dict: dict[str, object], prefix: str = 'module.') -> dict[str, object] {
    if not all(key.startswith(prefix) for key in state_dict.keys()) {
        return state_dict;
    }
    stripped_state_dict = dict();
    for key in state_dict {
        stripped_state_dict[key.replace(prefix, '')] = state_dict[key];
    }
    return stripped_state_dict;
}

glob BYTE_SHIFT = 0x100;
glob WORD_MASK = 0xffff;
glob NIBBLE_SHIFT = 0x10;
glob NIBBLE_CARRY = 0x1000;

"""Bit-rotate 0xAB 0xCD into 0xDA 0xBC and bit-invert result"""
def decode_word(byte1: int, byte2: int) -> tuple[int, int] {
    word = (byte1 * BYTE_SHIFT + byte2) ^ WORD_MASK;
    rotated = word // NIBBLE_SHIFT + (word % NIBBLE_SHIFT) * NIBBLE_CARRY;
    return (rotated // BYTE_SHIFT, rotated % BYTE_SHIFT);
}

"""Prime factorication.

    Parameters
    ----------
      n : int
        Value which should be factorized into primes.
    """
def prime_factors(n: int) -> list[int] {
    i = 2;
    factors = [];
    while i * i <= n {
        if n % i {
            i += 1;
        } else {
            n //= i;
            factors.append(i);
        }
    }
    if n > 1 {
        factors.append(n);
    }
    return factors;
}

