"""
    Strips a prefix from a string, if the string starts with the prefix.

    :param string: String that should have its prefix removed
    :param strip: Prefix to be removed
    :return: string with the prefix removed if it has the prefix, or else it
        just returns the original string
    """
def strip_prefix(string: str, strip: str) -> str {
    import re;
    strip_esc = re.escape(strip);
    if re.match(strip_esc, string) {
        return string[len(strip):];
    } else {
        return string;
    }
}

""" Find oldest time object in "bak_dir_time_objs" structure.
        recurse_val = 0 -> start with top entry "year", default
    """
def find_old_backup(bak_dir_time_objs: list[list[int]], recurse_val: int = 0) -> list[int] {
    tmp = [timeobj[recurse_val] for timeobj in bak_dir_time_objs];
    min_val = min(tmp);
    new_timeobj = [timeobj for timeobj in bak_dir_time_objs if timeobj[recurse_val] == min_val];
    if len(new_timeobj) > 1 {
        return find_old_backup(new_timeobj, recurse_val + 1);
    } else {
        return new_timeobj[0];
    }
}

"""Determine the index of greatest byte that isn't all zeros, and
