"""
    Args:
        list of strings
    Output:
        list of strings without repeated words ('no more more please' -> 'no
        more please')
    """
def deldoubleword(data: list[str]) -> list[str] {
    data = [x.split() for x in data];
    datalist = [];
    for sen in data {
        sen2 = [];
        for i in range(len(sen)) {
            if sen[i - 1] != sen[i] {
                sen2.append(sen[i]);
            }
        }
        senstring = ''.join(x + ' ' for x in sen2).rstrip();
        datalist.append(senstring);
    }
    return datalist;
}

"""
    Format data for bulk indexing into elasticsearch
    """
def format_data(data: dict, es_index: str) -> list[dict] {
    unit = data["unit"];
    rate_unit = data["rateUnit"];
    egvs = data["egvs"];
    docs = [];
    for record in egvs {
        record["unit"] = unit;
        record["rate_unit"] = rate_unit;
        record["@timestamp"] = record.pop("systemTime");
        record.pop("displayTime");
        record["realtime_value"] = record.pop("realtimeValue");
        record["smoothed_value"] = record.pop("smoothedValue");
        record["trend_rate"] = record.pop("trendRate");
        docs.append({"_index": es_index, "_type": "document", "_source": record});
    }
    return docs;
}

"""
    Function that returns the names of the parameters for writing to the dataframe after the fit.
    num_pars is the number of parameters in the fit. 1,3,5,7,9 are the num_params that constrain the fit.
    while the even numbers are the parameters for the functions that don't constrain the fits.
    """
def _return_parameter_names(num_pars: int) -> list[str] {
    match num_pars {
        case 1 | 2:
            return ['C_a', 'tau_a'];
        case 3:
            return ['C_a', 'tau_a', 'tau_b'];
        case 4:
            return ['C_a', 'tau_a', 'C_b', 'tau_b'];
        case 5:
            return ['C_a', 'tau_a', 'C_b', 'tau_b', 'tau_g'];
        case 6:
            return ['C_a', 'tau_a', 'C_b', 'tau_b', 'C_g', 'tau_g'];
        case 7:
            return ['C_a', 'tau_a', 'C_b', 'tau_b', 'C_g', 'tau_g', 'tau_d'];
        case 8:
            return ['C_a', 'tau_a', 'C_b', 'tau_b', 'C_g', 'tau_g', 'C_d', 'tau_d'];
        case 9:
            return ['C_a', 'tau_a', 'C_b', 'tau_b', 'C_g', 'tau_g', 'C_d', 'tau_d', 'tau_e'];
        case 10:
            return ['C_a', 'tau_a', 'C_b', 'tau_b', 'C_g', 'tau_g', 'C_d', 'tau_d', 'C_e', 'tau_e'];
        case _:
            return [];
    }
}

"""
    Check that the type of value is the Python equivalent of var_type or a list
    of it

    @param var_type (string) Type of val (INTEGER, REAL, LOGICAL, STRING)
    @param val (int/boolean/float/string/list) Value to check

    @return The value in (int, float, boolean, string)
    """
def check_type(var_type: str, value: bool | int | float | str | list[bool | int | float | str]) -> bool {
    res = True;
    if var_type in ['LOGIQUE', 'LOGICAL'] {
        py_type = bool;
    } elif var_type in ['ENTIER', 'INTEGER'] {
        py_type = int;
    } elif var_type in ['REEL', 'REAL'] {
        py_type = float;
    } else {
        py_type = str;
    }
    if isinstance(value, list) {
        for val in value {
            res = res and isinstance(val, py_type);
        }
    } else {
        res = isinstance(value, py_type);
    }
    return res;
}

"""Keeps the username of an email address."""
def username(email: str) -> str {
    return email and email.split('@', 1)[0];
}

"""Any single key"""
def any_key(m: list) -> str {
    return str(m[0]);
}

"""
    Checks if a point is unhappy. Returns False if happy.
    """
def unhappy_point(values: list[int], index: int) -> bool {
    if values[index] == values[index - 1] or values[index] == values[(index + 1) % len(values)] {
        return False;
    }
    return True;
}

"""
    Computes greatest common divisor (gcd) and coefficients of Bezout's identity
    for provided integers `a` and `b` using extended Euclidean Algorithm.

    Args:
        a (long): First integer number.
        b (long): Second integer number.

    Returns:
        (long, long, long): Three-tuple representing
        (gcd, Bezout's identity coefficient, Bezout's identity coefficient).
    """
def egcd(a: int, b: int) -> tuple[int, int, int] {
    r1 = a;
    r2 = b;
    s1 = 1;
    s2 = 0;
    t1 = 0;
    t2 = 1;
    while r2 > 0 {
        q = r1 // r2;
        r = r1 - q * r2;
        r1 = r2;
        r2 = r;
        s = s1 - q * s2;
        s1 = s2;
        s2 = s;
        t = t1 - q * t2;
        t1 = t2;
        t2 = t;
    }
    return (r1, s1, t1);
}

"""If _source if None, return an empty string, otherwise return string.
    This is useful when you build strings and want it to be empty if you don't have any data.
    For example when building a comma-separated string with a dynamic number of parameters:
    .. code-block:: python

    command = (_id +";" +  +  empty_if_none(";"+str(_comment), _comment))
    """
def empty_if_none(_string: str, _source: str | None = None) -> str {
    if _source is None {
        return "";
    } else {
        return str(_string);
    }
}

"""
    Returns a list of the contents of seq with sublists and tuples "exploded".
    The resulting list does not contain any sequences, and all inner sequences
    are exploded.  For example:

    >>> flatten([7,(6,[5,4],3),2,1])
    [7, 6, 5, 4, 3, 2, 1]
    """
def flatten(seq: list) -> list {
    lst = [];
    for el in seq {
        if isinstance(el, (list, tuple)) {
            lst.extend(flatten(el));
        } else {
            lst.append(el);
        }
    }
    return lst;
}
